import * as AasStringification from "../src/stringification";
import * as AasTypes from "../src/types";

test("Kind stringification round-trip Alpha", () => {
  const literal = AasTypes.Kind.Alpha;

  const text = AasStringification.mustKindToString(literal);
  expect(text).toStrictEqual("alpha");

  const nullableText = AasStringification.kindToString(literal);
  expect(nullableText).toStrictEqual("alpha");

  const parsed = AasStringification.kindFromString(text);
  expect(parsed).toStrictEqual(literal);
});

