test("Kind from invalid string", () => {
  const parsed = AasStringification.kindFromString(
    "invalid-literal"
  );

  expect(parsed).toBeNull();
});

test("Kind invalid literal to string", () => {
  // The number 9007199254740991 is the maximum safe integer.
  const invalidLiteral = <AasTypes.Kind>9007199254740991;

  expect(AasStringification.kindToString(invalidLiteral)).toBeNull();
  expect(() => AasStringification.mustKindToString(invalidLiteral)).toThrow();
});

